<template><view class="page"><SearchBar v-model="query" placeholder="代理名称、应用或流 ID" @search="reload"/><view class="list"><view v-for="item in items" :key="item.id" class="card"><view class="card__top"><text class="card__title">{{item.name||item.stream||'未命名代理'}}</text><StatusBadge :value="item.pulling??item.status"/></view><text class="card__meta">应用：{{item.app||'-'}}\n流 ID：{{item.stream||'-'}}</text></view><EmptyState v-if="!loading&&!items.length" title="暂无拉流代理"/><view v-if="items.length" class="footer">{{loading?'加载中…':finished?'没有更多了':'上拉加载更多'}}</view></view></view></template>
<script setup lang="ts">
import{ref}from'vue';import{onPullDownRefresh,onReachBottom,onLoad}from'@dcloudio/uni-app';import SearchBar from'@/components/SearchBar.vue';import EmptyState from'@/components/EmptyState.vue';import StatusBadge from'@/components/StatusBadge.vue';import{queryProxies,type StreamItem}from'@/api/stream';import{showRequestError}from'@/utils/request'
const query=ref(''),items=ref<StreamItem[]>([]),page=ref(1),loading=ref(false),finished=ref(false);async function load(reset=false){if(loading.value||(!reset&&finished.value))return;if(reset){page.value=1;finished.value=false}loading.value=true;try{const r=await queryProxies({page:page.value,count:20,query:query.value,pulling:'',mediaServerId:''});const list=r.list||r.items||[];items.value=reset?list:[...items.value,...list];finished.value=list.length<20;page.value++}catch(e){showRequestError(e)}finally{loading.value=false;uni.stopPullDownRefresh()}}function reload(){load(true)}onLoad(()=>load(true));onPullDownRefresh(reload);onReachBottom(()=>load())
</script><style lang="scss" scoped>@use '@/styles/list.scss';</style>
